# ── Lookup ─────────────────────────────────────────────────────────────────────

_UUID_RE = _re.compile(
    r'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$', _re.I
)

def get(label: str) -> str | None:
    """
    Look up a Claude-generated answer for this label.
    Returns the answer string, or None if not found.
    Matching is case-insensitive and partial (label contains key).
    """
    if not label:
        return None
    label_l = label.lower().strip()

    # Exact match first
    if label_l in CLAUDE_QA:
        return CLAUDE_QA[label_l]

    # Partial match — key appears anywhere in label
    for key, answer in CLAUDE_QA.items():
        if len(key) >= 5 and key in label_l:
            return answer

    return None


# ── Auto-save ──────────────────────────────────────────────────────────────────

_THIS_FILE = _Path(__file__)

def save(label: str, answer: str) -> None:
    """
    Save a Claude-generated answer into this file permanently.
    The entry is appended to the CLAUDE_QA dict in the source file itself
    so it survives across runs and is human-readable.
    """
    if not label or not answer or not str(answer).strip():
        return

    key = label.lower().strip()
    # Skip very short keys — too generic to be useful
    if len(key) < 4:
        return
    # Skip if already saved
    if key in CLAUDE_QA:
        return

    # Add to in-memory dict for this run
    CLAUDE_QA[key] = answer

    # Write into the source file — insert before the closing }
    try:
        src = _THIS_FILE.read_text(encoding="utf-8")
        # Escape the key and answer for Python string representation
        safe_key    = key.replace("\\", "\\\\").replace('"', '\\"')
        safe_answer = str(answer).replace("\\", "\\\\").replace('"', '\\"')
        new_entry   = f'    "{safe_key}": "{safe_answer}",\n'

        # Insert just before the closing } of CLAUDE_QA
        marker = "\n}\n"
        if marker in src:
            src = src.replace(marker, f"\n{new_entry}}}\n", 1)
            _THIS_FILE.write_text(src, encoding="utf-8")
            print(f"          💾 Saved to claude_answers.py: '{key[:50]}' → '{safe_answer[:40]}'")
    except Exception as e:
        print(f"          ⚠  Could not save to claude_answers.py: {e}")


# ── Stats ──────────────────────────────────────────────────────────────────────

def stats() -> dict:
    return {
        "total_claude_answers": len(CLAUDE_QA),
        "file": str(_THIS_FILE),
    }


def print_stats() -> None:
    print(f"  🤖 claude_answers.py: {len(CLAUDE_QA)} saved answers")


# ── CLI ────────────────────────────────────────────────────────────────────────
if __name__ == "__main__":
    print_stats()
    if CLAUDE_QA:
        print("\n  Saved answers:")
        for q, a in list(CLAUDE_QA.items())[:30]:
            print(f"    {q[:60]:60} → {str(a)[:40]}")
    else:
        print("  (no answers saved yet — they will appear here after the first run)")
